"""Generate the compact RuVector capability promo. No external assets or fonts."""
from pathlib import Path
from html import escape
css='''text{font-family:Arial,Helvetica,sans-serif}.track{stroke-dasharray:8 22;animation:track 4s linear infinite}.stage{animation:stage 16s ease-in-out infinite}.beam{animation:beam 4s ease-in-out infinite}.orbit{transform-box:fill-box;transform-origin:center;animation:orbit 20s linear infinite}.scan{animation:scan 4s ease-in-out infinite}.reveal{animation:reveal 16s ease-out infinite}.cta{animation:cta 4s ease-in-out infinite}@keyframes track{to{stroke-dashoffset:-120}}@keyframes stage{0%,25%,100%{stroke:#284656;fill:#101b29}3%,22%{stroke:#27eaff;fill:#17333e}}@keyframes beam{0%,100%{opacity:.25}50%{opacity:1}}@keyframes orbit{to{transform:rotate(360deg)}}@keyframes scan{0%,100%{transform:translateY(0)}50%{transform:translateY(21px)}}@keyframes reveal{0%{opacity:.3;transform:translateY(5px)}5%,95%{opacity:1;transform:translateY(0)}100%{opacity:.3}}@keyframes cta{0%,100%{stroke:#2b6f7c}50%{stroke:#7af4ff}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}'''
s=f'''<svg xmlns="http://www.w3.org/2000/svg" width="640" height="316" viewBox="0 0 640 316" role="img" aria-labelledby="title desc"><title id="title">RuVector: search, remember, connect and learn</title><desc id="desc">Local semantic embeddings and vector retrieval. Persistent memory across sessions. Graph relationships. Learning from recorded outcomes and explicit feedback. Rust native core. Illustration, not live metrics.</desc><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#122034"/><stop offset="1" stop-color="#080c15"/></linearGradient><linearGradient id="line"><stop stop-color="#27eaff"/><stop offset="1" stop-color="#ff319b"/></linearGradient></defs><style>{css}</style><rect x="1" y="1" width="638" height="314" rx="12" fill="url(#bg)" stroke="#2b4558"/><path d="M20 24V16H142M620 291V300H510" fill="none" stroke="#ff3ba0" stroke-width="2"/><text x="28" y="34" fill="#ff7cbc" font-size="9" letter-spacing="2.6">RUFLO ECOSYSTEM / RUST NATIVE</text><g class="reveal"><text x="26" y="75" fill="#f5f6f2" font-size="38" font-weight="700" letter-spacing="-1.5">RuVector</text><text x="222" y="60" fill="#ffe53d" font-size="13" font-weight="700">MEMORY THAT MOVES</text><text x="222" y="79" fill="#aec9dc" font-size="12">Search. Remember. Connect. Learn.</text></g><path d="M28 96H612" stroke="#244252"/><path class="track" d="M28 96H612" stroke="url(#line)" stroke-width="2"/>'''
items=[(28,110,'01','SEMANTIC SEARCH','Local embeddings +','vector retrieval.','search'),(329,110,'02','PERSISTENT MEMORY','Carry useful context','across agent sessions.','memory'),(28,190,'03','GRAPH RELATIONSHIPS','Connect entities and','related knowledge.','graph'),(329,190,'04','FEEDBACK LEARNING','Learn from outcomes','and explicit feedback.','learn')]
for i,(x,y,num,title,a,b,kind) in enumerate(items):
 s+=f'<g transform="translate({x} {y})"><rect class="stage" style="animation-delay:{i*4}s" width="283" height="70" rx="8" fill="#101b29" stroke="#284656"/><text x="12" y="18" fill="#ff74b7" font-size="9">{num}</text><text x="37" y="21" fill="#eaf4fc" font-size="12" font-weight="700" letter-spacing=".6">{title}</text><text x="37" y="40" fill="#adc8da" font-size="12">{a}</text><text x="37" y="56" fill="#adc8da" font-size="12">{b}</text><g transform="translate(249 39)" fill="none" stroke="#27eaff" stroke-width="1.5">'
 if kind=='search':s+='<circle r="17" stroke-opacity=".3"/><path d="M-12 -10H7M-12 0H7M-12 10H7" stroke-opacity=".4"/><path class="scan" d="M-15 -11H11" stroke="#ffe53d"/><circle cx="10" cy="6" r="6"/><path d="M14 11L21 17"/>'
 if kind=='memory':s+='<ellipse cy="-14" rx="17" ry="5"/><path d="M-17 -14V15C-17 23 17 23 17 15V-14M-17 0C-17 8 17 8 17 0"/><path class="beam" d="M-10 10H4M-10 14H10" stroke="#ffe53d"/>'
 if kind=='graph':s+='<path d="M-16 -10L0 4L15 -13M0 4L14 18M0 4L-18 16" stroke-opacity=".5"/><path class="track" d="M-16 -10L0 4L15 -13"/><g fill="#27eaff"><circle cx="-16" cy="-10" r="3"/><circle class="beam" cy="4" r="4"/><circle cx="15" cy="-13" r="3"/><circle cx="14" cy="18" r="3"/><circle cx="-18" cy="16" r="3"/></g>'
 if kind=='learn':s+='<g class="orbit"><circle r="19" stroke-dasharray="40 20"/><path d="M19 0L15 -5M19 0L23 -5" stroke="#ff50a8"/></g><path class="beam" d="M-8 0L-2 6L9 -7" stroke="#ffe53d"/>'
 s+='</g></g>'
s+='''<text x="28" y="285" fill="#92b0c4" font-size="10">Local retrieval · optional shared memory</text><text x="28" y="300" fill="#7c99ad" font-size="9">Learning depends on recorded feedback.</text><rect class="cta" x="420" y="274" width="192" height="28" rx="5" fill="#13323c" stroke="#2b6f7c"/><text x="434" y="292" fill="#7af4ff" font-size="11" font-weight="700">EXPLORE RUVECTOR</text><path d="M584 288H600M595 283L600 288L595 293" stroke="#7af4ff" fill="none" stroke-width="1.5"/></svg>'''
Path(__file__).with_name('ruvector-promo.svg').write_text(s)
